"""Ranked moment attribution on conserved dark residuals; no pixel correction."""
from datetime import datetime,timezone
import json
from pathlib import Path

import numpy as np

from measure_noise_opening_stages import read_crops
from study_noise_neighbourhoods import ROOT,sha256,git
from study_noise_residual_distributions import pack_cfa


FRACTIONS=(.0001,.001,.01,.05)


def contributions(a,b):
    a,b=np.asarray(a,dtype=float),np.asarray(b,dtype=float)
    if a.shape!=b.shape or a.ndim!=3 or min(a.shape[:2])<8 or not np.isfinite(a).all() or not np.isfinite(b).all():
        raise ValueError('Finite matching multichannel fields required')
    d=(a-b)/np.sqrt(2.);d-=d.mean(axis=(0,1));rows=[]
    for c in range(d.shape[-1]):
        v=d[:,:,c].ravel();v2=v*v;v4=v2*v2;s2=float(v2.sum());s4=float(v4.sum())
        if s2<=0 or s4<=0:raise ValueError('Positive moments required')
        order=np.argsort(-v2,kind='stable')
        ranks=[]
        for f in FRACTIONS:
            n=max(1,int(np.ceil(f*v.size)));ix=order[:n]
            ranks.append(dict(requested_fraction=f,count=n,actual_fraction=n/v.size,
                second_moment_share=float(v2[ix].sum()/s2),fourth_moment_share=float(v4[ix].sum()/s4)))
        rows.append(dict(channel=c,sigma=float(np.sqrt(s2/(v.size-1))),population_excess_kurtosis=float(v.size*s4/(s2*s2)-3),ranks=ranks,
            top16_yx=[[int(i//d.shape[1]),int(i%d.shape[1])] for i in order[:16]]))
    return rows


def coordinate_traces(crops):
    a,b=[c['post_dcp_rec2020'] for c in crops]
    ranking=contributions(a,b);coords=sorted({tuple(p) for r in ranking for p in r['top16_yx']})
    residuals={stage:(crops[0][stage].astype(float)-crops[1][stage].astype(float))/np.sqrt(2.) for stage in crops[0]}
    means={s:v.mean(axis=(0,1)) for s,v in residuals.items()}
    result=[]
    for y,x in coords:
        stages={}
        for stage in crops[0]:
            stages[stage]=dict(a=crops[0][stage][y,x].tolist(),b=crops[1][stage][y,x].tolist(),
                centered_residual=(residuals[stage][y,x]-means[stage]).tolist())
        raw=[c['pre_rcd_scaled_cfa'][max(0,y-2):min(128,y+3),max(0,x-2):min(128,x+3),0].tolist() for c in crops]
        result.append(dict(y=y,x=x,stages=stages,pre_rcd_neighborhoods_a_b=raw))
    return result


def run():
    start=datetime.now(timezone.utc);stamp=start.strftime('%Y%m%dT%H%M%SZ');base=ROOT/'docs/validation/raw'
    paths=[base/n for n in ('repetabilite-distributions-noirs-v001-20261028T114512Z.json','distributions-residus-bruit-v001-20261028T113008Z.json')]
    hashes=[sha256(p) for p in paths];real,simulation=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    freeze=base/f'gel-contributions-extremes-bruit-v001-{stamp}.json'
    policy=dict(campaign_id='noise-extreme-contributions-freeze-'+stamp,schema_version=1,data_version=1,measured_at_utc=start.isoformat(),
        parents=[dict(path=str(p),sha256=h) for p,h in zip(paths,hashes)],fractions=list(FRACTIONS),top_coordinates_per_channel=16,
        policy='All30 real ROIs from10 original disjoint dark pairs, roles unchanged, plus16 simulated pairs per6 pilot cases. Rank absolute centered paired residuals. Attribute squared/fourth moments to top0.01/0.1/1/5 percent, ceil count and ties stable. Trace union of top16 per RGB channel after DCP at exact same coordinates in all cached stages, pre-RCD5x5 neighborhoods, no causal one-pixel equivalence. Compute same-coordinate top16 overlaps between real disjoint pairs perISO/ROI/channel, record expected random overlap16*16/16384 only as descriptive reference, no pvalue. No removal, winsorization, new threshold, fit, RAW decode or production modification.',
        runner_source=Path(__file__).read_text(encoding='utf-8'),runner_sha256=sha256(Path(__file__)))
    with freeze.open('x',encoding='utf-8') as h:json.dump(policy,h,ensure_ascii=False,indent=1,allow_nan=False)
    print('FROZEN',freeze,flush=True)
    cached={}
    for source,item in real['native'].items():
        if sha256(Path(item['path']))!=item['sha256'] or sha256(Path(item['pixels']['path']))!=item['pixels']['sha256']:raise ValueError('Real native changed')
        cached[source]=read_crops(Path(item['pixels']['path']),item['record'])
    records=[]
    for r in real['records']:
        roi=r['roi'];crops=[{s:v[roi][64:192,64:192] for s,v in cached[p].items()} for p in r['paths']]
        stages={}
        for stage in crops[0]:
            values=[c[stage] for c in crops]
            if stage=='pre_rcd_scaled_cfa':values=[pack_cfa(v) for v in values]
            stages[stage]=contributions(*values)
        trace=coordinate_traces(crops)
        # Native arrays preserve ROI order at each stage.
        rects=[s['rect'] for s in real['native'][r['paths'][0]]['record']['stages'] if s['stage']=='post_dcp_rec2020']
        for t in trace:t['native_yx']=[rects[roi][1]+64+t['y'],rects[roi][0]+64+t['x']]
        records.append(dict(pair_index=r['pair_index'],iso=r['iso'],subset=r['subset'],roi=roi,paths=r['paths'],stages=stages,traces=trace))
    overlaps=[]
    for i,a in enumerate(records):
        for b in records[i+1:]:
            if (a['iso'],a['roi'])!=(b['iso'],b['roi']):continue
            for c in range(3):
                aa={tuple(x) for x in a['stages']['post_dcp_rec2020'][c]['top16_yx']};bb={tuple(x) for x in b['stages']['post_dcp_rec2020'][c]['top16_yx']}
                overlaps.append(dict(iso=a['iso'],roi=a['roi'],channel=c,pair_indices=[a['pair_index'],b['pair_index']],subsets=[a['subset'],b['subset']],intersection_count=len(aa&bb),intersection_yx=[list(p) for p in sorted(aa&bb)]))
    pixel_path=Path(simulation['pixels']['path']);native_path=Path(simulation['native']['path'])
    if sha256(pixel_path)!=simulation['pixels']['sha256'] or sha256(native_path)!=simulation['native']['sha256']:raise ValueError('Simulation changed')
    data=np.fromfile(pixel_path,dtype='<f4');native=json.loads(native_path.read_text(encoding='utf-8'));sim_records=[]
    for r in native['records']:
        crops={}
        for s in r['samples']:
            offset=s['offset_bytes']//4;count=int(np.prod(s['shape']))
            if offset<0 or offset+count>data.size:raise ValueError('Invalid simulation extent')
            crops[(s['stage'],s['trial'])]=data[offset:offset+count].reshape(s['shape'])
        for trial in range(0,32,2):
            stages={}
            for stage in ('pre_rcd_scaled_cfa','post_rcd_median_camera_rgb','post_dcp_rec2020'):
                values=[crops[(stage,t)] for t in (trial,trial+1)]
                if stage=='pre_rcd_scaled_cfa':values=[pack_cfa(v) for v in values]
                stages[stage]=contributions(*values)
            sim_records.append(dict(case_id=r['case_id'],trials=[trial,trial+1],stages=stages))
    if len(records)!=30 or len(sim_records)!=96 or hashes!=[sha256(p) for p in paths]:raise ValueError('Coverage/provenance failed')
    now=datetime.now(timezone.utc);out=base/f'contributions-extremes-bruit-v001-{now.strftime("%Y%m%dT%H%M%SZ")}.json'
    result=dict(campaign_id='noise-extreme-contributions-'+stamp,schema_version=1,data_version=1,started_at_utc=start.isoformat(),measured_at_utc=now.isoformat(),completed_at_utc=now.isoformat(),parents=policy['parents'],freeze=dict(path=str(freeze),sha256=sha256(freeze)),records=records,simulated=sim_records,overlaps=overlaps,
        units='Dimensionless shares of centered squared/fourth residual sums; normalized stage residuals; crop and native pixel coordinates.',
        limitations='Selection uses outcome ranks: attribution oracle, not deployable defect detector. Rank fractions fixed, not production thresholds. Same-coordinate traces do not prove CFA-to-RGB one-pixel causality; RCD uses neighborhoods and channels. Pair differences remove common defects; recurrent ranks are not proof of hot pixels. Same-session repeated inspection, no independent image-quality validation, no pixel removal, RAW decode, production change or final reserve access.',verdict='ranked_moment_attribution_only',commit=git('rev-parse','HEAD'))
    with out.open('x',encoding='utf-8') as h:json.dump(result,h,ensure_ascii=False,indent=1,allow_nan=False)
    print('RESULT',out,flush=True)


if __name__=='__main__':run()
